from sklearn.utils.stats import _weighted_percentile
import numpy as np


def weekly_kpi(actual, forecast, demand_weight):
    \"\"\"Demand-weighted median absolute forecast error for one week (lower is better).\"\"\"
    abs_errors = np.abs(np.array(actual) - np.array(forecast))
    return float(_weighted_percentile(abs_errors, sample_weight=demand_weight, percentile_rank=50, average=False))

